		meta.config.allowGuestHandles = 1;
		const result = await helpers.request('post', `/api/v3/topics`, {
			form: {
				title: 'just a title',
				cid: categoryObj.cid,
				content: 'content for the main post',
				handle: 'guest123',
			},
			jar: request.jar(),
